// ============================================================
//  Datenerfassung: Roh-Eingaben säubern & strukturieren
//  Aufgabe der Schreibkraft – hier automatisiert:
//  - Felder trimmen, Groß-/Kleinschreibung vereinheitlichen
//  - Preis als Zahl, EAN prüfen, Zustand normalisieren
//  - Eindeutige Artikelnummer (SKU) erzeugen
// ============================================================

const b = $json.body || $json;

const clean = (v) => (typeof v === 'string' ? v.trim().replace(/\s+/g, ' ') : v);
const titleCase = (v) =>
  clean(v)
    ? clean(v)
        .toLowerCase()
        .replace(/\b\p{L}/gu, (c) => c.toUpperCase())
    : '';

// Zustand auf Standardwerte mappen (Goldmine-Grading)
const zustandMap = {
  m: 'Mint (M)',
  nm: 'Near Mint (NM)',
  'vg+': 'Very Good Plus (VG+)',
  vg: 'Very Good (VG)',
  g: 'Good (G)',
  neu: 'Neu/OVP',
};
const zRaw = (clean(b.zustand) || '').toLowerCase();
const zustand = zustandMap[zRaw] || clean(b.zustand) || 'unbekannt';

// Format normalisieren
const formatRaw = (clean(b.format) || '').toLowerCase();
let format = 'Sonstige';
if (/lp|vinyl|schallplatte|12/.test(formatRaw)) format = 'Vinyl LP';
else if (/single|7"|45/.test(formatRaw)) format = 'Vinyl Single';
else if (/cd/.test(formatRaw)) format = 'CD';

// Preis säubern -> Zahl
const preis = Number(
  String(b.preis ?? '')
    .replace(/[^0-9,.]/g, '')
    .replace(/\.(?=\d{3})/g, '')
    .replace(',', '.')
) || 0;

// EAN/Barcode prüfen (8 oder 13 Stellen)
const eanRaw = String(b.ean ?? '').replace(/\D/g, '');
const eanOk = eanRaw.length === 8 || eanRaw.length === 13;

const kuenstler = titleCase(b.kuenstler || b.artist);
const titel = clean(b.titel || b.title);

// SKU: VC-<Format-Kürzel>-<Jahr>-<Zufall>
const kuerzel = format.startsWith('Vinyl') ? 'VIN' : format === 'CD' ? 'CD' : 'XX';
const sku =
  'VC-' +
  kuerzel +
  '-' +
  new Date().getFullYear() +
  '-' +
  Math.random().toString(36).slice(2, 7).toUpperCase();

// Pflichtfelder prüfen
const fehlend = [];
if (!kuenstler) fehlend.push('Künstler');
if (!titel) fehlend.push('Titel');
if (!preis) fehlend.push('Preis');

return [
  {
    json: {
      sku,
      kuenstler,
      titel,
      format,
      zustand,
      label: clean(b.label) || '',
      jahr: clean(b.jahr) || '',
      ean: eanOk ? eanRaw : '',
      ean_warnung: eanRaw && !eanOk ? 'EAN ungültig (' + eanRaw + ')' : '',
      preis,
      bestand: Number(b.bestand) || 1,
      beschreibung: clean(b.beschreibung) || '',
      erfasst_von: clean(b.erfasst_von) || 'Schreibkraft',
      erfasst_am: new Date().toISOString(),
      gueltig: fehlend.length === 0,
      fehlende_felder: fehlend,
    },
  },
];
